// Do not edit this file.

package searchrotated

import "testing"

func check(t *testing.T, nums []int, target, want int) {
	t.Helper()
	if got := Search(nums, target); got != want {
		t.Fatalf("Search(%v, %d) = %d, want %d", nums, target, got, want)
	}
}

func TestFoundAfterPivot(t *testing.T)    { check(t, []int{4, 5, 6, 7, 0, 1, 2}, 0, 4) }
func TestFoundBeforePivot(t *testing.T)   { check(t, []int{4, 5, 6, 7, 0, 1, 2}, 5, 1) }
func TestMissing(t *testing.T)            { check(t, []int{4, 5, 6, 7, 0, 1, 2}, 3, -1) }
func TestNotRotated(t *testing.T)         { check(t, []int{1, 2, 3, 4, 5}, 4, 3) }
func TestPivotAtEnd(t *testing.T)         { check(t, []int{2, 3, 4, 5, 1}, 1, 4) }
func TestPivotAtStart(t *testing.T)       { check(t, []int{5, 1, 2, 3, 4}, 5, 0) }
func TestEmpty(t *testing.T)              { check(t, []int{}, 1, -1) }
func TestSingleHit(t *testing.T)          { check(t, []int{1}, 1, 0) }
func TestSingleMiss(t *testing.T)         { check(t, []int{1}, 0, -1) }
func TestTwoElementsRotated(t *testing.T) { check(t, []int{3, 1}, 1, 1) }
